const timesheetDate = $input.first().json.body?.timesheetDate;
if (!timesheetDate) {
  throw new Error('timesheetDate is required (format: M/D/YYYY or MM/DD/YYYY)');
}
const parts = timesheetDate.split('/');
if (parts.length !== 3) {
  throw new Error('Invalid date format. Use M/D/YYYY');
}
const month = parseInt(parts[0]).toString().padStart(2, '0');
const day = parseInt(parts[1]).toString().padStart(2, '0');
const year = parts[2];
const formattedDate = year + '.' + month + '.' + day;
const basePath = '/app/n8n/timesheet/output';
const outputPath = basePath + '/' + formattedDate;
const templatePath = '/app/n8n/timesheet/n8n-workflows/templates';
return {
  json: {
    timesheetDate: timesheetDate,
    formattedDate: formattedDate,
    folderName: formattedDate,
    outputPath: outputPath,
    templatePath: templatePath,
    basePath: basePath
  }
};

const { execSync } = require('child_process');
const outputPath = $input.first().json.outputPath;
const templatePath = $input.first().json.templatePath;
const formattedDate = $input.first().json.formattedDate;
const wordTemplatePath = templatePath + '/RossNanton-Invoice-yyyy.mm.dd.docx';
const wordOutputPath = outputPath + '/RossNanton-Invoice-' + formattedDate + '.docx';
try {
  execSync('cp "' + wordTemplatePath + '" "' + wordOutputPath + '"');
  return {
    json: {
      success: true,
      fileCopied: 'Word',
      sourcePath: wordTemplatePath,
      outputPath: wordOutputPath,
      timesheetDate: $input.first().json.timesheetDate,
      formattedDate: $input.first().json.formattedDate,
      folderName: $input.first().json.folderName,
      basePath: $input.first().json.basePath
    }
  };
} catch (error) {
  throw new Error('Failed to copy Word template: ' + error.message);
}

const { execSync } = require('child_process');
const outputPath = $input.first().json.outputPath;
const templatePath = $input.first().json.templatePath;
const formattedDate = $input.first().json.formattedDate;
const excelTemplatePath = templatePath + '/RossNanton-Timesheet-yyyy.mm.dd.xlsx';
const excelOutputPath = outputPath + '/RossNanton-Timesheet-' + formattedDate + '.xlsx';
try {
  execSync('cp "' + excelTemplatePath + '" "' + excelOutputPath + '"');
  return {
    json: {
      success: true,
      fileCopied: 'Excel',
      sourcePath: excelTemplatePath,
      outputPath: excelOutputPath,
      excelFilePath: excelOutputPath,
      timesheetDate: $input.first().json.timesheetDate,
      formattedDate: $input.first().json.formattedDate,
      folderName: $input.first().json.folderName,
      basePath: $input.first().json.basePath
    }
  };
} catch (error) {
  throw new Error('Failed to copy Excel template: ' + error.message);
}

const { execSync } = require('child_process');
const excelFilePath = $input.first().json.excelFilePath;
const timesheetDate = $input.first().json.timesheetDate;
const formattedDate = $input.first().json.formattedDate;
const folderName = $input.first().json.folderName;
if (!excelFilePath) {
  throw new Error('Excel file path not provided');
}
if (!timesheetDate) {
  throw new Error('Timesheet date not provided');
}
try {
  const result = execSync('node /app/n8n/timesheet/n8n-workflows/scripts/update-excel.js "' + excelFilePath + '" E8 "' + timesheetDate + '"', { encoding: 'utf8' });
  const parsed = JSON.parse(result);
  if (!parsed.success) {
    throw new Error(parsed.error);
  }
  return {
    json: {
      success: true,
      fileUpdated: 'Excel (Cell E8)',
      filePath: excelFilePath,
      cellE8Updated: timesheetDate,
      timesheetDate: timesheetDate,
      formattedDate: formattedDate,
      folderName: folderName
    }
  };
} catch (error) {
  throw new Error('Failed to update Excel file: ' + error.message);
}

const result = $input.first().json;
return {
  json: {
    status: 'success',
    message: 'Timesheet setup completed successfully',
    details: {
      timesheetDate: result.timesheetDate,
      folderName: result.folderName,
      outputPath: result.outputPath,
      filesCreated: [
        'RossNanton-Invoice-' + result.formattedDate + '.docx',
        'RossNanton-Timesheet-' + result.formattedDate + '.xlsx (Cell E8 updated: ' + result.timesheetDate + ')'
      ]
    }
  }
};
